  ('nhs-first-solids', jsonb_build_object('en', 'Your baby''s first solid foods', 'bn', 'শিশুর প্রথম শক্ত খাবার'), 'NHS', 'https://www.nhs.uk/conditions/baby/weaning-and-feeding/babys-first-solid-foods/', 2026, 'patient_info'),
  ('nhs-foods-to-avoid-babies', jsonb_build_object('en', 'Foods to avoid giving babies and young children', 'bn', 'শিশুদের যেসব খাবার দেওয়া উচিত নয়'), 'NHS', 'https://www.nhs.uk/conditions/baby/weaning-and-feeding/foods-to-avoid-giving-babies-and-young-children/', 2026, 'patient_info'),
  ('who-iycf', jsonb_build_object('en', 'Infant and young child feeding (fact sheet)', 'bn', 'শিশু ও ছোট বাচ্চার খাওয়ানো (তথ্যপত্র)'), 'WHO', 'https://www.who.int/news-room/fact-sheets/detail/infant-and-young-child-feeding', 2026, 'patient_info'),
