INSERT INTO posts (slug, title, excerpt, body, tags, reading_minutes, published_on) VALUES ('starting-solid-foods', '{"en": "Starting solid foods: what, when and how", "bn": "শক্ত খাবার শুরু: কী, কখন আর কীভাবে"}'::jsonb, '{"en": "Around six months, a baby is ready to start tasting food. Here is how to begin calmly, with soft, single foods, safe textures and no added salt or sugar.", "bn": "প্রায় ছয় মাসে শিশু খাবারের স্বাদ নিতে তৈরি হয়। নরম, একটি একটি খাবার, নিরাপদ গঠন আর বাড়তি লবণ-চিনি ছাড়া কীভাবে শান্তভাবে শুরু করবেন, এখানে দেখুন।"}'::jsonb, '{"en": ["Until about six months, breast milk, or first infant formula, gives your baby most of the energy and nutrients they need. Around six months, a baby starts to be ready for a first taste of other food. WHO and the NHS give the same starting point.", "## Signs that your baby is ready", "The NHS lists three signs that appear together from about six months:", "- they can sit up and hold their head steady", "- they can look at food, pick it up and put it in their mouth", "- they can swallow food rather than spit it back out", "Chewing fists, waking at night and wanting extra milk are common, but the NHS says they are not reliable signs of readiness.", "## What to start with", "- Begin with single vegetables or fruit, mashed or soft-cooked: sweet potato, potato, carrot, pumpkin, apple or pear.", "- Include vegetables that are not sweet, so your baby gets used to different tastes.", "- Move on from purées to mashed, lumpy and soft finger foods as soon as your baby can manage them.", "- From about six months, the NHS says foods that can cause allergies, such as egg, peanut, gluten and fish, can be introduced one at a time in small amounts. If there is allergy in the family, talk to a doctor or health worker first.", "- From about seven to nine months, include iron-rich foods such as meat, fish, lentils and beans, dark green vegetables and fortified cereals.", "## How often and how much", "WHO suggests starting with small amounts and increasing gradually: two to three meals a day at six to eight months, and three to four meals a day from nine months, with snacks if needed. Keep breastfeeding as often as your baby wants; breast milk still gives about half of a baby''s energy at six to twelve months.", "## Keep it safe", "- Stay with your baby while they eat.", "- Do not add salt or sugar to food or cooking water.", "- Cut round foods, such as grapes, into quarters, and take out pips and bones. Avoid whole nuts and hard raw pieces.", "- Gagging is common and normal as babies learn; choking is different and needs your immediate attention.", "This is general guidance from the NHS and WHO, not medical advice. Your doctor or local health worker knows your baby; follow their advice, especially for a premature baby, an allergy in the family, or any worry about feeding or growth."], "bn": ["প্রায় ছয় মাস পর্যন্ত বুকের দুধ, বা প্রথম ধাপের ফর্মুলা দুধ, শিশুর প্রয়োজনীয় বেশিরভাগ শক্তি ও পুষ্টি জোগায়। প্রায় ছয় মাসে শিশু অন্য খাবারের প্রথম স্বাদ নিতে তৈরি হতে শুরু করে। WHO ও NHS দুজনেই একই সূচনার কথা বলে।", "## শিশু তৈরি কি না, বুঝবেন যেভাবে", "NHS তিনটি লক্ষণের কথা বলে, যা প্রায় ছয় মাস থেকে একসঙ্গে দেখা যায়:", "- সে সোজা হয়ে বসতে পারে এবং মাথা স্থির রাখতে পারে", "- সে খাবারের দিকে তাকাতে, তুলে নিতে আর মুখে দিতে পারে", "- সে খাবার গিলে ফেলতে পারে, ঠেলে বের করে দেয় না", "মুঠো চিবানো, রাতে জেগে ওঠা আর বাড়তি দুধ চাওয়া সাধারণ, কিন্তু NHS বলে এগুলো তৈরি হওয়ার নির্ভরযোগ্য লক্ষণ নয়।", "## কী দিয়ে শুরু করবেন", "- একটি একটি সবজি বা ফল দিয়ে শুরু করুন, চটকে বা নরম সেদ্ধ করে: মিষ্টি আলু, আলু, গাজর, মিষ্টি কুমড়া, আপেল বা নাশপাতি।", "- মিষ্টি নয় এমন সবজিও দিন, যাতে শিশু নানা স্বাদে অভ্যস্ত হয়।", "- শিশু সামলাতে পারলেই পিউরি থেকে চটকানো, দানাদার আর নরম আঙুল-খাবারে যান।", "- NHS বলে, প্রায় ছয় মাস থেকে ডিম, চীনাবাদাম, গ্লুটেন আর মাছের মতো অ্যালার্জি হতে পারে এমন খাবার একটি একটি করে অল্প পরিমাণে দেওয়া যায়। পরিবারে অ্যালার্জি থাকলে আগে ডাক্তার বা স্বাস্থ্যকর্মীর সঙ্গে কথা বলুন।", "- প্রায় সাত থেকে নয় মাস থেকে আয়রনসমৃদ্ধ খাবার দিন, যেমন মাংস, মাছ, ডাল ও শিম, গাঢ় সবুজ সবজি আর পুষ্টি-মেশানো সিরিয়াল।", "## কতবার, কতটা", "WHO অল্প পরিমাণে শুরু করে ধীরে ধীরে বাড়াতে বলে: ছয় থেকে আট মাসে দিনে দুই-তিনবার, নয় মাস থেকে দিনে তিন-চারবার, দরকারে নাস্তাসহ। শিশু যতবার চায় বুকের দুধ চালিয়ে যান; ছয় থেকে বারো মাসে বুকের দুধ এখনও শিশুর শক্তির প্রায় অর্ধেক জোগায়।", "## নিরাপদে খাওয়ান", "- শিশু খাওয়ার সময় তার সঙ্গে থাকুন।", "- খাবারে বা রান্নার পানিতে লবণ-চিনি দেবেন না।", "- আঙুরের মতো গোল খাবার চার টুকরা করুন, বিচি ও কাঁটা বের করুন। গোটা বাদাম আর শক্ত কাঁচা টুকরা এড়ান।", "- শিশু শেখার সময় ওক ওঠা স্বাভাবিক; দম আটকে যাওয়া ভিন্ন, তাতে এখনই মনোযোগ দিতে হয়।", "এটি NHS ও WHO-র সাধারণ পরামর্শ, চিকিৎসা-পরামর্শ নয়। আপনার ডাক্তার বা স্থানীয় স্বাস্থ্যকর্মী আপনার শিশুকে চেনেন; তাঁদের কথা মানুন, বিশেষ করে অপরিণত শিশু, পরিবারে অ্যালার্জি বা খাওয়ানো বা বৃদ্ধি নিয়ে কোনো দুশ্চিন্তা থাকলে।"]}'::jsonb, '["baby", "feeding", "weaning"]'::jsonb, 3, '2026-11-23') ON CONFLICT (slug) DO NOTHING;
INSERT INTO post_sources (post_id, source_id, sort) SELECT p.id, s.id, 0 FROM posts p JOIN sources s ON s.key = 'nhs-first-solids' WHERE p.slug = 'starting-solid-foods' ON CONFLICT DO NOTHING;
