INSERT INTO posts (slug, title, excerpt, body, tags, reading_minutes, published_on) VALUES ('breastfeeding-first-two-years', '{"en": "Breastfeeding in the first two years", "bn": "প্রথম দুই বছরে বুকের দুধ"}'::jsonb, '{"en": "WHO advises breast milk only for the first six months, then breast milk alongside safe food up to two years or beyond. Here is what that means day to day.", "bn": "WHO প্রথম ছয় মাস শুধু বুকের দুধ, তারপর দুই বছর বা তার বেশি পর্যন্ত নিরাপদ খাবারের সঙ্গে বুকের দুধের পরামর্শ দেয়। দৈনন্দিন জীবনে এর মানে কী, দেখুন।"}'::jsonb, '{"en": ["WHO advises starting breastfeeding within the first hour after birth, giving only breast milk for the first six months, and then continuing to breastfeed up to two years or beyond, with safe food added from six months.", "## Why it matters", "The NHS notes that breastfed babies have fewer infections, less diarrhoea and vomiting, and a lower risk of sudden infant death and of obesity later on. It says any amount of breast milk has a positive effect, and lists lower risks of breast and ovarian cancer, osteoporosis, heart disease, obesity and diabetes for the mother.", "## Alongside food", "- At six to twelve months, breast milk still gives about half of your baby''s energy; at twelve to twenty-four months, about one third.", "- Keep breastfeeding often as you add food; breast milk or formula stays the main drink in the first year.", "- Respond to your baby''s signs of hunger and fullness, and keep hands, utensils and food clean.", "## If feeding is hard", "Pain, a baby who is not gaining weight, or any worry about feeding is a reason to talk to a doctor, nurse or trained breastfeeding supporter early; help works best sooner.", "This is general guidance from the NHS and WHO, not medical advice. Your doctor or local health worker knows your baby; follow their advice, especially for a premature baby, an allergy in the family, or any worry about feeding or growth."], "bn": ["WHO জন্মের পর প্রথম এক ঘণ্টার মধ্যে বুকের দুধ শুরু করতে, প্রথম ছয় মাস শুধু বুকের দুধ দিতে, আর তারপর ছয় মাস থেকে নিরাপদ খাবার যোগ করে দুই বছর বা তার বেশি পর্যন্ত বুকের দুধ চালিয়ে যেতে পরামর্শ দেয়।", "## কেন জরুরি", "NHS বলে বুকের দুধ খাওয়া শিশুর সংক্রমণ কম হয়, ডায়রিয়া-বমি কম হয়, আর হঠাৎ শিশুমৃত্যু ও পরে স্থূলতার ঝুঁকি কমে। যেকোনো পরিমাণ বুকের দুধেই উপকার আছে, আর মায়ের স্তন ও ডিম্বাশয়ের ক্যান্সার, হাড়ক্ষয়, হৃদরোগ, স্থূলতা ও ডায়াবেটিসের ঝুঁকি কমে বলে তারা উল্লেখ করে।", "## খাবারের পাশাপাশি", "- ছয় থেকে বারো মাসে বুকের দুধ এখনও শিশুর শক্তির প্রায় অর্ধেক জোগায়; বারো থেকে চব্বিশ মাসে প্রায় এক-তৃতীয়াংশ।", "- খাবার যোগ করলেও ঘন ঘন বুকের দুধ চালিয়ে যান; প্রথম বছরে বুকের দুধ বা ফর্মুলাই মূল পানীয়।", "- শিশুর ক্ষুধা ও পেট ভরার ইঙ্গিতে সাড়া দিন, আর হাত, বাসনপত্র ও খাবার পরিষ্কার রাখুন।", "## খাওয়ানো কঠিন হলে", "ব্যথা, শিশুর ওজন না বাড়া বা খাওয়ানো নিয়ে যেকোনো দুশ্চিন্তায় আগেই ডাক্তার, নার্স বা প্রশিক্ষিত সহায়তাকারীর সঙ্গে কথা বলুন; আগে সাহায্য নিলে ভালো কাজ হয়।", "এটি NHS ও WHO-র সাধারণ পরামর্শ, চিকিৎসা-পরামর্শ নয়। আপনার ডাক্তার বা স্থানীয় স্বাস্থ্যকর্মী আপনার শিশুকে চেনেন; তাঁদের কথা মানুন, বিশেষ করে অপরিণত শিশু, পরিবারে অ্যালার্জি বা খাওয়ানো বা বৃদ্ধি নিয়ে কোনো দুশ্চিন্তা থাকলে।"]}'::jsonb, '["baby", "breastfeeding", "mother"]'::jsonb, 2, '2026-11-23') ON CONFLICT (slug) DO NOTHING;
INSERT INTO post_sources (post_id, source_id, sort) SELECT p.id, s.id, 0 FROM posts p JOIN sources s ON s.key = 'who-iycf' WHERE p.slug = 'breastfeeding-first-two-years' ON CONFLICT DO NOTHING;
INSERT INTO post_sources (post_id, source_id, sort) SELECT p.id, s.id, 1 FROM posts p JOIN sources s ON s.key = 'nhs-breastfeeding-benefits' WHERE p.slug = 'breastfeeding-first-two-years' ON CONFLICT DO NOTHING;
INSERT INTO posts (slug, title, excerpt, body, tags, reading_minutes, published_on) VALUES ('foods-to-avoid-for-babies', '{"en": "Foods to keep away from babies and young children", "bn": "শিশু ও ছোট বাচ্চাদের যে খাবার দেওয়া ঠিক নয়"}'::jsonb, '{"en": "Honey before one year, added salt and sugar, whole nuts and a few other foods are not safe for little ones. Here is the NHS list, in plain words.", "bn": "এক বছরের আগে মধু, বাড়তি লবণ-চিনি, গোটা বাদামসহ কিছু খাবার ছোটদের জন্য নিরাপদ নয়। NHS-এর তালিকা সহজ ভাষায় দেখুন।"}'::jsonb, '{"en": ["Some foods are fine for the family but not for a baby. The NHS gives this list.", "## Do not give", "- Honey until your baby is over one year old: it can cause infant botulism.", "- Added salt: babies should not have much salt because it is hard on their kidneys. Salty foods such as sausages, crisps, ready meals and takeaways are best avoided.", "- Added sugar, syrup and sweeteners for children aged four and under. This includes fruit juice and smoothies; whole fruit is fine.", "- Whole nuts for children under five, because they can cause choking. Ground nuts or nut butter spread thinly on food are fine from about six months, unless a doctor has said otherwise because of allergy in the family.", "- Rice drinks for children under five.", "- Raw or lightly cooked shellfish, and raw jelly cubes.", "## Take care with", "- Eggs: from about six months, cooked until solid unless they carry the British Lion stamp.", "- Cheese: pasteurised full-fat cheese is fine from six months; check the label.", "- Round, hard or slippery foods: cut grapes into quarters and take out pips and bones.", "This is general guidance from the NHS and WHO, not medical advice. Your doctor or local health worker knows your baby; follow their advice, especially for a premature baby, an allergy in the family, or any worry about feeding or growth."], "bn": ["কিছু খাবার পরিবারের জন্য ঠিক, কিন্তু শিশুর জন্য নয়। NHS এই তালিকা দেয়।", "## দেবেন না", "- শিশুর বয়স এক বছর পেরোনোর আগে মধু: এতে শিশুর বটুলিজম হতে পারে।", "- বাড়তি লবণ: শিশুর বেশি লবণ খাওয়া উচিত নয় কারণ এতে কিডনির ওপর চাপ পড়ে। সসেজ, চিপস, তৈরি খাবার আর বাইরের খাবারের মতো লবণাক্ত খাবার এড়ানোই ভালো।", "- চার বছর বা তার কম বয়সীদের বাড়তি চিনি, সিরাপ ও মিষ্টি দেওয়ার উপাদান। ফলের রস ও স্মুদিও এর মধ্যে পড়ে; আস্ত ফল দেওয়া যায়।", "- পাঁচ বছরের কম বয়সীদের গোটা বাদাম, কারণ এতে দম আটকাতে পারে। গুঁড়া বাদাম বা পাতলা করে মাখানো বাদামের মাখন প্রায় ছয় মাস থেকে দেওয়া যায়, তবে পরিবারে অ্যালার্জির কারণে ডাক্তার অন্যথা বললে নয়।", "- পাঁচ বছরের কম বয়সীদের চালের পানীয়।", "- কাঁচা বা আধা-সেদ্ধ শামুক-ঝিনুক-চিংড়িজাতীয় খাবার, আর কাঁচা জেলির টুকরা।", "## সতর্ক থাকুন", "- ডিম: প্রায় ছয় মাস থেকে, শক্ত হওয়া পর্যন্ত সেদ্ধ করে।", "- পনির: পাস্তুরিত পূর্ণ-চর্বির পনির ছয় মাস থেকে ঠিক; মোড়ক দেখে নিন।", "- গোল, শক্ত বা পিচ্ছিল খাবার: আঙুর চার টুকরা করুন, বিচি ও কাঁটা বের করুন।", "এটি NHS ও WHO-র সাধারণ পরামর্শ, চিকিৎসা-পরামর্শ নয়। আপনার ডাক্তার বা স্থানীয় স্বাস্থ্যকর্মী আপনার শিশুকে চেনেন; তাঁদের কথা মানুন, বিশেষ করে অপরিণত শিশু, পরিবারে অ্যালার্জি বা খাওয়ানো বা বৃদ্ধি নিয়ে কোনো দুশ্চিন্তা থাকলে।"]}'::jsonb, '["baby", "safety", "feeding"]'::jsonb, 2, '2026-11-23') ON CONFLICT (slug) DO NOTHING;
INSERT INTO post_sources (post_id, source_id, sort) SELECT p.id, s.id, 0 FROM posts p JOIN sources s ON s.key = 'nhs-foods-to-avoid-babies' WHERE p.slug = 'foods-to-avoid-for-babies' ON CONFLICT DO NOTHING;
